draw(arc(O[2],r[2],0,180));
draw(A--P--B);

label("$A$", A, NW);
label("$B$", B, NE);
label("$P$", P, N);
label("$R$", R, dir(270));
label("$S$", S, SW);
label("$T$", T, SE);
[/asy]
